{
  "coverage_questions": [
    {
      "peril": "Water damage from groundwater seepage through slab cracks",
      "facts": "Loss date 11 June 2024 after three days of heavy rain; water entered basement through cracks in the slab; carpet and drywall wet to 8 inches; no plumbing failure found; sump pump was working; no surface water entry at doors or windows.",
      "forms": ["HO-0304"]
    },
    {
      "peril": "Removal (tear‑out) of wet basement finishes (carpet, drywall) as part of water damage remediation",
      "facts": "Basement carpet and drywall saturated to 8 inches; insured is requesting payment for basement tear‑out; water intrusion caused by the same seepage event described above.",
      "forms": ["HO-0304"]
    }
  ]
}

{
  "coverage_questions": [
    {
      "peril": "Water damage from dishwasher overflow",
      "facts": "Dishwasher overflowed on 2 May 2024, causing flooding of the kitchen floor. Unit is 17 years old per the serial plate; insured confirms it was never serviced.",
      "forms": ["HO-0304"]
    },
    {
      "peril": "Damage to kitchen floor and lower cabinets",
      "facts": "Floor and lower cabinets damaged by the dishwasher overflow; repair estimate $6,200. Deductible $1,000.",
      "forms": ["HO-0304"]
    }
  ]
}

{
  "coverage_questions": [
    {
      "peril": "Sudden accidental water damage from burst copper supply line",
      "facts": "Copper supply line to the laundry burst on 29 June 2024 while insured was away; plumber's report indicates pipe split along a seam, a single sudden failure with no evidence of prior leakage; drywall behind pipe was dry before the split; damage estimate $11,800; deductible $1,000; claim reported on 6 July (five days after discovery).",
      "forms": ["HO-0304"]
    }
  ]
}

{
  "coverage_questions": [
    {
      "peril": "Theft of personal property from home office",
      "facts": "Burglary occurred on 10 Oct 2024 at the insured's residence. Stolen items: laptop, two monitors, docking station, all located in a spare-room office. Receipts total $3,400. Deductible $500 per policy. Insured works from home two days a week but no clients visit and no signage indicating a business.",
      "forms": ["HO-0309"]
    },
    {
      "peril": "Business use of home office – coverage of business equipment",
      "facts": "The stolen items (laptop, monitors, docking station) were used in a home office where the insured performs work for her employer two days per week. No clients ever visit the home, and there is no signage indicating a business. Policy HO-0309 may have exclusions or endorsements for business property.",
      "forms": ["HO-0309"]
    }
  ]
}

{
  "coverage_questions": [
    {
      "peril": "Sudden burst of kitchen water supply line causing water damage",
      "facts": "Kitchen supply line burst on 20 June 2024; water damage estimate $9,300; reported within 36 hours; policy forms HO-0304 ed. 03-24 and HO-0306 ed. 04-24; deductible $1,000.",
      "forms": ["HO-0304", "HO-0306"]
    },
    {
      "peril": "Mold growth and remediation following water damage",
      "facts": "Mold appeared 10 days after the burst; licensed remediation contractor written estimate $12,600; insured paid $600 for mold air sampling; same policy forms HO-0304 ed. 03-24 and HO-0306 ed. 04-24; mold linked to the water damage event.",
      "forms": ["HO-0304", "HO-0306"]
    }
  ]
}

{
  "coverage_questions": [
    {
      "peril": "Roof damage and water intrusion from Hurricane Helene",
      "facts": "Hurricane Helene (named storm) on 26 Sep 2024 tore roof panels; rain entered the home; loss estimate $21,000; Coverage A limit $280,000; all‑peril deductible $1,000; policy forms HO-0304 and HO-0305 in effect.",
      "forms": ["HO-0304", "HO-0305"]
    },
    {
      "peril": "Water damage from dishwasher supply line burst",
      "facts": "Dishwasher supply line burst on 3 Oct 2024; loss estimate $4,800; reported same day; loss is from a sudden, accidental water discharge; Coverage A limit $280,000; all‑peril deductible $1,000; policy forms HO-0304 and HO-0305 in effect.",
      "forms": ["HO-0304", "HO-0305"]
    }
  ]
}

{
  "coverage_questions": [
    {
      "peril": "Storm surge water damage to dwelling (Coverage A)",
      "facts": "Policy forms HO-0305 ed. 03-24 and HO-0306 ed. 04-24; Coverage A limit $400,000; Storm surge from Hurricane Helene pushed seawater through the ground floor on 26 Sep 2024; No wind damage to the structure; Damage estimate $38,000; No NFIP flood policy in place.",
      "forms": ["HO-0305", "HO-0306"]
    },
    {
      "peril": "Potential flood exclusion applicability",
      "facts": "Storm surge is seawater intrusion caused by a hurricane; Policy does not contain a separate flood endorsement; No NFIP flood policy in place; Standard HO-5/HO-6 policies typically exclude flood (including storm surge) damage.",
      "forms": ["HO-0305", "HO-0306"]
    }
  ]
}

{
  "coverage_questions": [
    {
      "peril": "Sinkhole damage to dwelling (foundation and floor)",
      "facts": "Sinkhole opened under the west corner of the house on 4 June 2024; foundation cracked; living room floor dropped.",
      "forms": ["HO-0307"]
    },
    {
      "peril": "Loss of scheduled Steinway piano due to sinkhole collapse",
      "facts": "Insured's scheduled Steinway piano (schedule value $42,000, appraisal 2024) fell through the floor and was destroyed when the sinkhole caused the floor to drop; deductible $1,000.",
      "forms": ["HO-0308"]
    }
  ]
}

{
  "coverage_questions": [
    {
      "peril": "Water damage from frozen pipe burst",
      "facts": "Heating was turned off and main water left on while the house was empty from February. Pipes froze and split on 20 March 2024. The split was discovered a week later by the letting agent. Damage estimate is $16,200. Policy deductible is $1,000. Policy form: HO-0304.",
      "forms": ["HO-0304"]
    },
    {
      "peril": "Loss of rental income / loss of use due to property being uninhabitable after pipe burst",
      "facts": "The property is a rental‑between‑tenants house that was empty from February. Damage from the frozen pipe burst rendered the house uninhabitable, preventing any rental income. Damage estimate is $16,200. Policy deductible is $1,000. Policy form: HO-0304.",
      "forms": ["HO-0304"]
    }
  ]
}

{
  "coverage_questions": [
    {
      "peril": "Loss of unscheduled jewelry (ring) with unknown cause",
      "facts": "Ring gone on 12 Aug 2024; insured does not know where or how it disappeared; the ring was not listed on the personal property schedule; policy deductible is $250; policy form HO-0307 is on file.",
      "forms": ["HO-0307"]
    }
  ]
}
